# tracer.py draws a GPX file

import gpxpy
import requests
import matplotlib.pyplot as plt
import json

class Tracer:
    def __init__(self, gpx_file, resolution, output_video_file):
        self.gpx_file = gpx_file
        self.resolution = resolution
        self.output_video_file = output_video_file

    def parse_gpx(self):
        # Use gpxpy to parse the GPX file and extract the route coordinates
        gpx = gpxpy.parse(open(self.gpx_file, 'r'))
        self.gpx = gpx
    
    # Ping Open Elevation API to get a relief map of the area of the GPX file
    def get_relief_map(self):
        # Use the coordinates from the GPX file to determine the bounding box for the map
        x_min = min(point.longitude for track in self.gpx.tracks for segment in track.segments for point in segment.points)
        x_max = max(point.longitude for track in self.gpx.tracks for segment in track.segments for point in segment.points)
        y_min = min(point.latitude for track in self.gpx.tracks for segment in track.segments for point in segment.points)
        y_max = max(point.latitude for track in self.gpx.tracks for segment in track.segments for point in segment.points)

        # Use the bounding box wih a margin to request a relief map from Open Elevation API
        margin = 0.5  # Define a margin in percentage of the bounding box size
        x_margin = (x_max - x_min) * margin
        y_margin = (y_max - y_min) * margin

        grid_points = self.create_grid(x_min - x_margin, x_max + x_margin, y_min - y_margin, y_max + y_margin)
        print(f"Requesting relief map for {len(grid_points)} points from Open Elevation API")
        # Convert grid_point in JSON format for the request
        data = {'locations': [{'longitude': x, 'latitude': y} for x, y in grid_points]}
        self.response = requests.post(f"https://api.open-elevation.com/api/v1/lookup", data=json.dumps(data), headers={'Content-Type': 'application/json', 'Accept': 'application/json'})

        # Check if the request was successful
        if self.response.status_code != 200:
            raise Exception(f"Request to Open Elevation API failed with status code {self.response.status_code}")
        # Parse JSON content
        json_content = json.loads(self.response.content.decode('utf-8'))
        print(f"Relief map content:\n{json_content}")

        # convert JSON response to [longitude, latitude, elevation] list
        self.elevation_data = [(result['longitude'], result['latitude'], result['elevation']) for result in json_content['results']]

    def create_grid(self, x_min: float, x_max: float, y_min: float, y_max: float) -> list[tuple[float, float]]:
        """
        Create a grid of points within the bounding box defined by the given coordinates.
        The grid will have a resolution of self.resolution.
        """
        grid_points = []
        i = 0
        while x_min + i * self.resolution < x_max:
            j = 0
            while y_min + j * self.resolution < y_max:
                grid_points.append((x_min + i * self.resolution, y_min + j * self.resolution))
                j += 1
            i += 1
        return list(set(grid_points))

    def create_elevation_plot(self):
        # Create a 2D plot of the elevation data seen from above. Elevation is represented by color, lower elevation is darker green and higher elevation is lighter green. The plot is saved to self.output_video_file.
        longitudes = [point[0] for point in self.elevation_data]
        latitudes = [point[1] for point in self.elevation_data]
        elevations = [point[2] for point in self.elevation_data]

        plt.figure(figsize=(10, 6))
        plt.scatter(longitudes, latitudes, c=elevations, cmap='Greens', s=1)

        # Add GPX track points to the plot
        track_longitudes = [point.longitude for track in self.gpx.tracks for segment in track.segments for point in segment.points]
        track_latitudes = [point.latitude for track in self.gpx.tracks for segment in track.segments for point in segment.points]
        plt.plot(track_longitudes, track_latitudes, color='red', linewidth=1)
        plt.colorbar(label='Elevation (m)')
        plt.xlabel('Longitude')
        plt.ylabel('Latitude')
        plt.title('Elevation Map')
        plt.savefig(self.output_video_file, dpi=300)

    def create_3d_plot(self):
        # Create a 3D plot of the elevation data. Elevation is represented by height, lower elevation is lower and higher elevation is higher. The plot is saved to self.output_video_file. The plot is a 3D surface plot with the GPX track points overlaid in red. The plot is interactive and can be rotated and zoomed in/out.
        from mpl_toolkits.mplot3d import Axes3D
        from mpl_toolkits.mplot3d.art3d import Line3DCollection

        longitudes = [point[0] for point in self.elevation_data]
        latitudes = [point[1] for point in self.elevation_data]
        elevations = [point[2] for point in self.elevation_data]

        fig = plt.figure(figsize=(10, 6))
        ax = fig.add_subplot(111, projection='3d')
        ax.plot_trisurf(
            longitudes,
            latitudes,
            elevations,
            cmap='Greys',
            linewidth=0.2,
            alpha=0.8,
            # zsort='min'
        )

        # Add GPX track points to the plot
        offset = 1000  # Offset to avoid z-fighting
        track_longitudes = [point.longitude for track in self.gpx.tracks for segment in track.segments for point in segment.points]
        track_latitudes = [point.latitude for track in self.gpx.tracks for segment in track.segments for point in segment.points]
        track_elevations = [point.elevation + offset for track in self.gpx.tracks for segment in track.segments for point in segment.points]

        line_coords = list(zip(track_longitudes, track_latitudes, track_elevations))
        track_line = Line3DCollection([line_coords], colors='red', linewidths=2)
        track_line.set_sort_zpos(1e6)
        # track_line.set_zorder(100)
        ax.add_collection3d(track_line)

        ax.set_xlabel('Longitude')
        ax.set_ylabel('Latitude')
        ax.set_zlabel('Elevation (m)')
        plt.title('3D Elevation Map')
        plt.show()
        # plt.savefig(self.output_video_file, dpi=300)
    
    def run(self):
        self.parse_gpx()
        self.get_relief_map()

